/**
 * Сбрасывает состояние сессии (счётчики, позицию мяча)
 */
function resetSession() {
  try {
    bbCounters.resetAll()
    if (isPlaying) {
      _setPlayPauseState(false)
    }
    safeSend(WS_MSG.controllerUpdate, {
      paused: true,
      returnToCenter: true
